return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'eu','project-id-version'=>'babilim-0.1.0-eu-babilim-0.1.0-eu-20261030T023517','pot-creation-date'=>'2026-10-30T06:25:23+00:00','po-revision-date'=>'2026-10-30T06:25:23+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Zure gunean instalatuta dauden plugin eta itxuretan falta diren itzulpenak betetzen ditu.','Translations'=>'Itzulpenak','Babilim Settings'=>'Babilim ezarpenak','Settings'=>'Ezarpenak','You are not allowed to do this.'=>'Ez duzu hori egiteko baimenik.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Hautatu osagai gutxiago: gehienez %1$d eragiketa exekuzioko (%2$d hautatu dituzu).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Osagai hori ez dago instalatuta gune honetan, beraz ezin da horretarako itzulpenik eskatu.','Already installed.'=>'Instalatuta dago jada.','Downloaded and installed.'=>'Deskargatu eta instalatu da.','Babilim has not been enabled for this site yet.'=>'Babilim ez dago oraindik gune honetan gaituta.','No build is available to download for this locale.'=>'Ez dago deskargatzeko konpilaziorik hizkuntza honetarako.','Rolled back to the previous build.'=>'Aurreko konpilaziora itzuli da.','Rolled back and reported.'=>'Atzera egin da eta salatu da.','Rolled back, but the report could not be sent: %s'=>'Atzera egin da, baina ezin izan da txostena bidali: %s','Removed.'=>'Kendu da.','Translation requested.'=>'Itzulpena eskatu da.','This component was already uploaded. Babilim is checking it now.'=>'Osagai hau jada kargatu zen. Babilim egiaztatzen ari da orain.','Upload cancelled.'=>'Kargatzea bertan behera utzi da.','Upload complete — translation requested.'=>'Kargatzea amaitu da — itzulpena eskatu da.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Osagai honek ez du bertsio-zenbakirik adierazten, beraz ezin da horretarako itzulpenik eskatu.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Osagai honen bertsio-zenbakia %d karaktere baino luzeagoa da, eta Babilim-ek ezin du kudeatu; beraz, ezin da horretarako itzulpenik eskatu.','A translation cannot be requested for that locale on this site right now.'=>'Une honetan ezin da hizkuntza horretarako itzulpenik eskatu gune honetan.','Thank you. Your report was sent.'=>'Eskerrik asko. Zure txostena bidali da.','This report does not name a valid plugin or theme and locale.'=>'Txosten honek ez du plugin edo itxura baten Izen baliozkorik eta hizkuntzarik zehazten.','Please choose a category for this report.'=>'Aukeratu kategoria bat txosten honetarako.','This report is missing a valid build to report against.'=>'Txosten honek ez du txostena egiteko build baliozkorik.','This build is not one this site currently knows about for this component/locale.'=>'Eraikitze hau ez da gune honek osagai/hizkuntza honetarako ezagutzen duen bat.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" eremua luzeegia da: %2$d karaktere ditu eta muga %3$d da. Ez da ezer bidali; laburtu eta saiatu berriro.','Original string'=>'Jatorrizko katea','String context'=>'Kateen testuingurua','Current translation'=>'Uneko itzulpena','Suggested translation'=>'Itzulpen iradokia','Note (optional)'=>'Oharra (aukerakoa)','Where you saw this (optional)'=>'Non ikusi duzun hau (aukerakoa)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim-en sinkronizazioa aldi baterako atzeratu du zerbitzuak (tasa mugatua); berriro saiatuko da %s ondoren.','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'Gehitu duzun hizkuntza ez da baliozkoa: erabili WordPress-en hizkuntza-kode bat, hala nola ll_CC (letrak, zifrak, azpimarra, gidoia edo @, gehienez %d karaktere). Ez da ezer gorde.','Settings saved.'=>'Ezarpenak gorde dira.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Aktibatuta badago, desinstalatzean gune honen identitatea ere ezabatuko da. Gune honi lotutako ordainpeko lizentzia ezin da gero automatikoki berreskuratu; Babilim-en laguntzarekin harremanetan jarri beharko zenuke hemen: %s.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim-ek gune honen identitatea ezabatzeko konfiguratuta dago plugina ezabatzen denean. Gune honi lotutako ordainpeko lizentzia ezin izango litzateke gero automatikoki berreskuratu; Babilim-en laguntzarekin harremanetan jarri beharko zenuke hemen: %s. Identitatea gordetzeko, sakatu Utzi, desmarkatu "Ezabatu Babilim-en datu guztiak desinstalatzean" Babilim-en ezarpenetan, eta desaktibatu berriro. Hala ere desaktibatu?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Sare honetako %1$d gune Babilim-en identitatea ezabatzeko konfiguratuta dago plugina ezabatzen denean. Gune horri lotutako ordainpeko lizentzia ezin izango litzateke gero automatikoki berreskuratu; Babilim-en laguntzarekin harremanetan jarri beharko zenuke hemen: %2$s. Identitatea gordetzeko, sakatu Utzi, desmarkatu "Ezabatu Babilim-en datu guztiak desinstalatzean" gune horren Babilim-en ezarpenetan, eta desaktibatu berriro. Hala ere desaktibatu?' . "\0" . 'Sare honetako %1$d gune Babilim-en identitatea ezabatzeko konfiguratuta daude plugina ezabatzen denean. Gune horiei lotutako ordainpeko lizentziak ezin izango lirateke gero automatikoki berreskuratu; Babilim-en laguntzarekin harremanetan jarri beharko zenuke hemen: %2$s. Identitateak gordetzeko, sakatu Utzi, desmarkatu "Ezabatu Babilim-en datu guztiak desinstalatzean" gune bakoitzaren Babilim-en ezarpenetan, eta desaktibatu berriro. Hala ere desaktibatu?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Sare honek gune gehiegi ditu banan-banan egiaztatzeko, eta horietako batzuk Babilim identitatea ezabatzeko konfiguratuta egon daitezke plugina ezabatzen denean. Orduan, gune horri lotutako ordainpeko lizentzia ezin izango litzateke automatikoki berreskuratu; Babilim-en laguntzarekin harremanetan jarri beharko zenuke hemen: %s. Identitateak mantentzeko, sakatu Utzi, desmarkatu "Ezabatu Babilim-en datu guztiak desinstalatzean" gune bakoitzeko Babilim ezarpenetan, eta desaktibatu berriro. Hala ere desaktibatu?','Open Babilim settings'=>'Ireki Babilim-en ezarpenak','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim-ek ezin izan du gune hau egiaztatu, beraz ez da ezer deskargatu edo instalatu.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Zerbitzua ezin izan da zure gunera iritsi. Ziurrenik suebaki batek, segurtasun-plugin batek edo ostatatze-arau batek eskaera blokeatzen du; mesedez, baimendu /wp-json/babilim/v1/challenge helbiderako eskaerak.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Zure guneak denbora gehiegi behar izan du erantzuteko. Saiatu berriro geroago, eta egiaztatu zure ostatatzea ez dagoela motelegi edo gainkargatuta.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Zure guneak erantzun du, baina ez espero zen erantzunarekin. Baliteke beste plugin batek REST API berridaztea edo amaiera-puntu hori cachean egotea; mesedez, kanpoan utzi /wp-json/babilim/v1/challenge cachetik eta berridazketatik.','Please check that your site can be reached from the internet, then try again.'=>'Egiaztatu zure gunera internetetik sar daitekeela, eta saiatu berriro.','Re-verify'=>'Egiaztatu berriro','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Gune honek zerbitzuak sinkronizazio bakoitzean onartzen duen tamaina gainditzen du, beraz elementu batzuk kanpoan geratu dira: %1$d osagai eta %2$d hizkuntza-eremu.','This site is verified.'=>'Gune hau egiaztatuta dago.','Registration restarted.'=>'Erregistroa berrabiarazi da.','Sync complete.'=>'Sinkronizazioa osatu da.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim gune hau gaitzen eta egiaztatzen ari da… Birkargatu orri hau edo itxaron programatutako egiaztapena amaitu arte.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim-ek ezin izan du gaitzea amaitu (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'PHP eskaera bakarra aldi berean zerbitzatzen duen ostatatze batek ezin du urrats hau osatu.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim gaituta dago: gune hau egiaztatuta dago eta %d osagai aurkitu da.' . "\0" . 'Babilim gaituta dago: gune hau egiaztatuta dago eta %d osagai aurkitu dira.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim desgaituta dago. Ez da ezer gehiago bidaltzen; dagoeneko instalatutako itzulpenek funtzionatzen jarraitzen dute.','Supplementary translation index rebuilt.'=>'Itzulpen-indize osagarria berreraiki da.','Sweep complete: %d file deleted.'=>'Arakatze-garbiketa osatu da: %d fitxategi ezabatu da.' . "\0" . 'Arakatze-garbiketa osatu da: %d fitxategi ezabatu dira.','Removed %d installed component.'=>'%d instalatutako osagai kendu da.' . "\0" . '%d instalatutako osagai kendu dira.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Instalazio automatikoak desaktibatuta daude orain; aktibatu berriro ezarpenetan nahi izanez gero.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim-ek gune honetan zure hizkuntzarako itzulpenik ez duten pluginak eta gaiak aurkitzen ditu, eta bakoitzarentzat bat instalatzen du.','Languages found on this site: %s.'=>'Gune honetan aurkitutako hizkuntzak: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Eskuragarri dauden itzulpenak klik batez instala daitezke, eta falta direnak eskatu. Ondoren, itzulpen berriak eta eguneratzeak automatikoki instalatzen dira (doako planean, dagoeneko doako plaza bat erabiltzen duten pluginetarako eta gaietarako soilik).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Doako planak plugin eta gai kopuru mugatua hartzen du; zure kuota zehatza Ezarpenak atalean ikusiko duzu Babilim gaitu ondoren.','What is sent when you enable Babilim'=>'Zer bidaltzen den Babilim gaitzean','Enabling…'=>'Gaitzen…','Enable Babilim'=>'Gaitu Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Gaitu sakatuz, goian zerrendatutako informazioa Babilim-i bidaltzea onartzen duzu.','Check again now'=>'Egiaztatu berriro orain','Babilim installed %d translation automatically since your last visit.'=>'Babilim-ek %d itzulpen instalatu du automatikoki zure azken bisitaz geroztik.' . "\0" . 'Babilim-ek %d itzulpen instalatu ditu automatikoki zure azken bisitaz geroztik.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim gune hau gaitzen eta egiaztatzen ari da… (azken saiakera: %s)','Check again'=>'Egiaztatu berriro','No components synced yet.'=>'Oraindik ez da osagairik sinkronizatu.','%d succeeded'=>'%d ondo atera da' . "\0" . '%d ondo atera dira','%d skipped'=>'%d saltatu da' . "\0" . '%d saltatu dira','%d failed'=>'%d huts egin du' . "\0" . '%d huts egin dute','%d not yet tried'=>'%d oraindik saiatu gabe' . "\0" . '%d oraindik saiatu gabe','Bulk %s:'=>'Multzokako %s:','%1$s nothing to do.'=>'%1$s ez dago ezer egiteko.','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Jarraitzen…','Continue next batch (%d left)'=>'Jarraitu hurrengo sortarekin (%d geratzen dira)','Search components'=>'Bilatu osagaiak','These are the languages this site uses. You can change them in %s.'=>'Hauek dira gune honek erabiltzen dituen hizkuntzak. %s atalean alda ditzakezu.','Upload this component?'=>'Osagai hau igo nahi duzu?','There is no upload waiting for confirmation.'=>'Ez dago berrespenaren zain dagoen igoerarik.','Back'=>'Atzera','To translate this component, Babilim needs its source.'=>'Osagai hau itzultzeko, Babilim-ek bere iturburua behar du.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'%1$s osagaiaren (%2$s bertsioa) plugin edo itxura direktorio osoa Babilim-era igoko da.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Direktorio horrek gakoak, erregistroak edo bezeroen datuak baditu, haiek ere igoko dira. Zerbitzuak fitxategi sentikor arruntak (konfigurazioa, ingurunea, datu-base kopiak, erregistroak, gakoak) kentzen ditu, baina ezin du bermatu dena aurkitzen duenik.','The upload is kept until you ask Babilim to delete it.'=>'Igoera hori gordeta egongo da Babilim-i ezabatzeko eskatu arte.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Zerbitzuaren ostatatze-hornitzaileak gordetzen du, eta AA ereduek prozesatzen dute itzulpena sortzeko.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Jatorrizko testua eta honetatik egindako itzulpenak bertsio bera instalatzen duten beste guneei emango zaizkie.','By continuing you confirm that you have the right to upload this component.'=>'Jarraituz gero, osagai hau igotzeko eskubidea duzula berresten duzu.','Upload and request'=>'Igo eta eskatu','Uploading…'=>'Igotzen…','Cancel'=>'Utzi','Uploading'=>'Igotzen','There is no upload in progress.'=>'Ez dago igoerarik abian.','Uploading part %1$d of %2$d…'=>'%2$d zatitik %1$d. zatia igotzen…','Continue'=>'Jarraitu','Confirm'=>'Berretsi','Remove'=>'Kendu','Roll back'=>'Leheneratu','Nothing to confirm.'=>'Ez dago berresteko ezer.','Choose a language'=>'Aukeratu hizkuntza bat','Roll back and report'=>'Leheneratu eta jakinarazi','Report a problem'=>'Jakinarazi arazo bat','Nothing to choose.'=>'Ez dago aukeratzeko ezer.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Aukeratu hizkuntza.','Supplementary translations'=>'Itzulpen osagarriak','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Osagai bakoitzak lokalizazio bakoitzaren domeinu lehenetsiaren eranskin partekatuari egiten dion ekarpena.','Component'=>'Osagaia','Language'=>'Hizkuntza','Included in index'=>'Indizean barne','Entries'=>'Sarrerak','Conflicting keys'=>'Gatazkatsuak diren gakoak','Yes'=>'Bai','No — component inactive'=>'Ez — osagaia ez dago aktibo','No — installed version differs from the active one'=>'Ez — instalatutako bertsioa ez da aktibo dagoen bertsioaren berdina','No — component removed'=>'Ez — osagaia kendu da','No'=>'Ez','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Sareko administratzaile batek bakarrik egin dezake hori, sare honetako gune guztiek partekatzen dituzten itzulpen-fitxategiak aldatzen dituelako.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim-ek ezin izan du gune hau egiaztatzea amaitu (zerbitzuak ezin izan du gunera berriro konektatu). Erregistroa geldituta dago.','This site already has an active registration that can no longer be recovered automatically.'=>'Gune honek jada erregistro aktibo bat du, eta ezin da automatikoki berreskuratu.','Restart registration'=>'Berrabiarazi erregistroa','Babilim settings'=>'Babilim-en ezarpenak','General'=>'Orokorra','Advanced'=>'Aurreratuak','Languages'=>'Hizkuntzak','Automatic installs'=>'Instalazio automatikoak','Install available translations automatically'=>'Instalatu eskuragarri dauden itzulpenak automatikoki','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Doako planean, zure leku libreetako bat erabiltzen duten osagaiak soilik instalatzen dira automatikoki, beraz ez da leku berririk hartzen.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Gune hau multisite sare baten parte da, eta horrek ez ditu itzulpen berriak automatikoki instalatzen. Dagoeneko instalatuta dauden itzulpenak eguneratzen dira.','Custom overrides'=>'Gainidazte pertsonalizatuak','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Mantendu nire itzulpen-gainidazteak dena garbitzean edo plugin hau desinstalatzean.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'%s karpetan jartzen dituzun itzulpen-fitxategiek lehentasuna dute beti Babilim-enen aurretik. Mantendu egiten dira, hau desmarkatzen ez baduzu.','Uninstall'=>'Desinstalatu','Delete all Babilim data on uninstall'=>'Ezabatu Babilim-en datu guztiak desinstalatzean','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Lehenespenez desaktibatuta: plugina ezabatzean gune honen identitatea gordetzen da, berriro instalatuz gero berrerabil dadin.','Account'=>'Kontua','Save changes'=>'Gorde aldaketak','Disable Babilim'=>'Desgaitu Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Instalatutako itzulpenak mantentzen dira, baina ez da egiaztapen edo deskargarik egingo.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim desgaitu? Instalatutako itzulpenak mantentzen dira, baina ez da egiaztapen edo deskargarik egingo.','This site is not registered with Babilim yet.'=>'Gune hau ez dago oraindik Babilim-en erregistratuta.','This site is already licensed. Reload the page.'=>'Gune honek jada lizentzia du. Birkargatu orria.','Checkout is not available for this site right now.'=>'Erosketa ez dago eskuragarri gune honetarako orain.','Could not start checkout: %s'=>'Ezin izan da erosketa hasi: %s','Babilim is not enabled.'=>'Babilim ez dago gaituta.','Not registered yet'=>'Oraindik erregistratu gabe','Not verified'=>'Egiaztatu gabe','Verified'=>'Egiaztatuta','Status'=>'Egoera','Licensed'=>'Lizentziadun','Partner'=>'Bazkidea','Free'=>'Doakoa','License'=>'Lizentzia','Upgrade this site'=>'Eguneratu gune hau','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Gune honetarako ordainketa bakarra: %1$s %2$s. Etorkizuneko itzulpen-eguneraketa guztiak barne. Ordainketa Paddle bidez kudeatzen da, fitxa berri batean.','This issues a new restore code and the previous one stops working. Continue?'=>'Honek berrezarketa-kode berri bat sortzen du eta aurrekoak funtzionatzeari uzten dio. Jarraitu?','Show a new restore code'=>'Erakutsi berrezarketa-kode berri bat','rc_…'=>'rc_…','Restore code'=>'Berrezarketa-kodea','Restore purchase'=>'Berrezarri erosketa','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Lehenago domeinu honetarako lizentzia erosi duzu? Sartu erosketan jaso zenuen berrezarketa-kodea.','That does not look like a restore code.'=>'Hori ez dirudi berrezarketa-kode bat denik.','This restore code was not recognised for this site.'=>'Berrezarketa-kode hau ez da gune honetarako aitortu.','Too many attempts. Try again tomorrow.'=>'Saiakera gehiegi. Saiatu berriro bihar.','This site must be verified first.'=>'Gune hau aurretik egiaztatu behar da.','Could not restore the purchase: %s'=>'Ezin izan da erosketa berrezarri: %s','Purchase restored. This site is now licensed.'=>'Erosketa berrezarri da. Gune honek lizentzia du orain.','This site has no purchase to show a code for.'=>'Gune honek ez du koderik erakusteko erosketarik.','Could not show a new restore code: %s'=>'Ezin izan da berrezarketa-kode berri bat erakutsi: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Zure berrezarketa-kode berria: %s. Gorde toki seguru batean: aurreko kodeak ez du funtzionatzen jada.','What is sent when Babilim checks this site'=>'Babilim-ek gune hau egiaztatzen duenean bidaltzen dena','(detected)'=>'(detektatuta)','No language is managed yet.'=>'Oraindik ez da hizkuntzarik kudeatzen.','Babilim adds translations for every language checked here.'=>'Babilim-ek hemen markatutako hizkuntza guztietarako itzulpenak gehitzen ditu.','Add another language'=>'Gehitu beste hizkuntza bat','Choose a language…'=>'Aukeratu hizkuntza bat…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Ezin izan da zerbitzutik WordPress.org-en hizkuntza-zerrenda osoa kargatu, beraz, une honetan ezin da beste hizkuntzarik gehitu.','Theme'=>'Itxura','Plugin'=>'Plugina','Free quota'=>'Doako kuota','Downloads: %1$d/%2$d (%3$s)'=>'Deskargak: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Itzulpen-indize osagarria','Built'=>'Eraikia','Included'=>'Barne','Excluded'=>'Kanpo','Already in WordPress core'=>'WordPress-en nukleoan badago jada','Supplementary translation maintenance'=>'Itzulpen-indize osagarriaren mantentze-lanak','Maintenance status is not available right now.'=>'Mantentze-lanen egoera ez dago eskuragarri une honetan.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Garbiketa bat eten da (%1$s): %2$s. Ez da ezer ezabatu.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Azken garbiketa (%1$s): %2$d fitxategi markatu dira, %3$d fitxategi ezabatu dira eta %4$d erregistro kendu dira.','No cleanup has run yet.'=>'Ez da oraindik garbiketarik egin.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Itzulpen-indizerako idazketa batek gatazka izan zuen beste eskaera batekin (%1$s; %2$s), eta ez zen aplikatu; bertsiorik berriena mantendu zen.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Itzulpen-indizerako idazketa bat (%1$s; %2$s) ezin izan da osatu, eta ez da aplikatu (%3$s).','Maintenance'=>'Mantentze-lanak','Rebuild index now'=>'Berreraiki indizea orain','Sweep now'=>'Egin arakatze-garbiketa orain','Danger zone'=>'Arrisku-eremua','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Babilim-ek gune honetako plugin eta itxura guztietarako instalatutako hizkuntza-fitxategi guztiak kentzen ditu.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim-ek instalatutako guztia kendu? Honek Babilim-ek gune honetako plugin eta itxura guztietarako instalatutako hizkuntza-fitxategi guztiak ezabatzen ditu.','Remove everything Babilim installed'=>'Kendu Babilim-ek instalatutako guztia','This string is too long to be sent as a report, so no report form is offered for it.'=>'Kate hau luzeegia da txosten gisa bidaltzeko, beraz ez da txostenik bidaltzeko formularioa eskaintzen.','Category'=>'Kategoria','Choose a category…'=>'Aukeratu kategoria bat…','Roll back and send report'=>'Leheneratu eta bidali txostena','Send report'=>'Bidali txostena','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Egileak osagai honen testuaren zati bat zuzenean kodean idatzi du, eta ezin da hizkuntza-pakete batekin itzuli.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Itxurarekin batera dator','Bundled with the plugin'=>'Pluginarekin batera dator','Upload was not accepted'=>'Igoera ez da onartu','Upload expired before it finished'=>'Igoera iraungi da amaitu aurretik','No translation'=>'Itzulpenik ez','Upload in progress — continue or cancel'=>'Igoera abian da — jarraitu edo utzi','Scheduled, waiting to be processed'=>'Programatuta, prozesatzeko zain','Translating…'=>'Itzultzen…','Translation failed'=>'Itzulpenak huts egin du','Free quota used'=>'Doako kuota erabilita','Needs a paid license'=>'Ordainpeko lizentzia behar du','Not supported'=>'Ez da onartzen','Status unknown'=>'Egoera ezezaguna','translation statusInstalled'=>'Instalatuta','Update available'=>'Eguneratzea eskuragarri','Removed after a failed integrity check'=>'Kendu da osotasun-egiaztapenak huts egin ondoren','Installed · built for %s, new version scheduled'=>'Instalatuta · %s bertsiorako eraikia, bertsio berria programatuta','Installed · built for a different version, new version scheduled'=>'Instalatuta · beste bertsio baterako eraikia, bertsio berria programatuta','Installed · built for %s, translating the new version…'=>'Instalatuta · %s bertsiorako eraikia, bertsio berria itzultzen…','Installed · built for a different version, translating the new version…'=>'Instalatuta · beste bertsio baterako eraikia, bertsio berria itzultzen…','Installed · built for %1$s, this site has %2$s'=>'Instalatuta · %1$s bertsiorako eraikia, gune honek %2$s du','Installed · built for %s'=>'Instalatuta · %s bertsiorako eraikia','Installed · built for a different version'=>'Instalatuta · beste bertsio baterako eraikia','Installed · built for %s, new version failed'=>'Instalatuta · %s bertsiorako sortua, bertsio berriak huts egin du','Installed · built for a different version, new version failed'=>'Instalatuta · beste bertsio baterako sortua, bertsio berriak huts egin du','Installed · built for %s, new version needs a paid license'=>'Instalatuta · %s bertsiorako sortua, bertsio berriak ordainpeko lizentzia behar du','Installed · built for a different version, new version needs a paid license'=>'Instalatuta · beste bertsio baterako sortua, bertsio berriak ordainpeko lizentzia behar du','Installed · built for %s, free quota used'=>'Instalatuta · %s bertsiorako sortua, doako kuota erabilita','Installed · built for a different version, free quota used'=>'Instalatuta · beste bertsio baterako sortua, doako kuota erabilita','translation statusAvailable'=>'Erabilgarri','Installed · %s'=>'Instalatuta · %s','Available · %s'=>'Erabilgarri · %s','Update'=>'Eguneratu','Download'=>'Deskargatu','Updating…'=>'Eguneratzen…','Downloading…'=>'Deskargatzen…','Retry request'=>'Errepikatu eskaera','Request newer translation'=>'Eskatu itzulpen berriagoa','Request translation'=>'Eskatu itzulpena','Requesting…'=>'Eskatzen…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Itzulpen bat eskatzeak zure leku libreetako bat erabiltzen du, osagai honek jada bat erabiltzen ez badu behintzat. Huts egindako itzulpen batek ez du lekua itzultzen.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Osagai honek oraindik zure leku libreetako bat erabiltzen ez badu, itzulpen bat eskatzeak bat erabiliko du. Huts egindako itzulpen batek ez du lekua itzultzen. Jarraitu?','No plugins or themes found.'=>'Ez da pluginik edo itxurarik aurkitu.','Clear filters'=>'Garbitu iragazkiak','No components match these filters. %s'=>'Ez dago iragazki hauekin bat datorren osagairik. %s','Select all'=>'Hautatu guztiak','All'=>'Guztiak','Available'=>'Erabilgarri','Updates'=>'Eguneraketak','Requestable'=>'Eska daiteke','Installed'=>'Instalatuta','Plugins'=>'Pluginak','Themes'=>'Itxurak','All languages'=>'Hizkuntza guztiak','%d to install'=>'%d instalatzeko' . "\0" . '%d instalatzeko','Language:'=>'Hizkuntza:','Bulk actions apply to every matching language of each selected component.'=>'Ekintza masiboak hautatutako osagai bakoitzaren bat datozen hizkuntza guztiei aplikatzen zaizkie.','Bulk actions apply only to the selected language of each selected component.'=>'Ekintza masiboak hautatutako osagai bakoitzaren hautatutako hizkuntzari soilik aplikatzen zaizkio.','Version %s'=>'%s bertsioa','Theme · %s'=>'Itxura · %s','Plugin · %s'=>'Plugina · %s','Remove the %2$s translation of %1$s from this site?'=>'%1$s osagaiaren itzulpena (%2$s) gune honetatik kendu nahi duzu?','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s osagaiaren itzulpena (%2$s) aurreko bertsiora leheneratu nahi duzu?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Erregistro-erronkak ez du espero den forma.','That is not a valid build identifier.'=>'Hori ez da eraikuntza-identifikatzaile baliozkoa.','Refusing to write outside the Babilim language-file directory.'=>'Babilim hizkuntza-fitxeren direktorioaren kanpoan idaztea ukatu da.','Could not write the downloaded package to disk.'=>'Ezin izan da deskargatutako paketea diskoan idatzi.','Unexpected HTTP %d response.'=>'Ustekabeko HTTP %d erantzuna.','This site\'s URL, so the service can verify you own it.'=>'Gune honen URLa, zerbitzuak zurea dela egiazta dezan.','Your WordPress version, to serve compatible translation files.'=>'Zure WordPress bertsioa, itzulpen-fitxategi bateragarriak eskaintzeko.','Your PHP version, for compatibility.'=>'Zure PHP bertsioa, bateragarritasunerako.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Plugin honen bertsioa, zerbitzuak eguneratzeko esan diezazun zaharregia bada komunikatzeko.','This site\'s configured locale.'=>'Gune honen konfiguratutako locale-a.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Gune honetan erabiltzen diren locale guztiak (guneko locale-a, instalatutako hizkuntza-paketeak, erabiltzaileen locale-ak eta eskuz gehitutakoak). Ez da locale bat bestea baino modu desberdinean tratatzen.','(a public key generated for this site)'=>'(gune honetarako sortutako gako publikoa)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Gune honen instalazioaren gako publikoa, eskaerak benetan gune honetatik datozela frogatzeko erabiltzen dena. Zati publikoa soilik bidaltzen da.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Instalatutako plugin/itxura bakoitza: bere slug-a, bertsioa, text domain-a(k), WordPress.org zerrendakoa den ala ez, berarekin datozen locale-ak eta Babilim itzulpena jada instalatuta duzun locale-ak.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'WordPress.org-en ez dagoen plugin edo itxura baten karga berretsi duzunean soilik: osagai horren direktorio osoa, zip gisa.','(generic codes and coordinates only)'=>'(kode eta koordenatu generikoak soilik)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Gehienez 20 diagnostiko-gertaera zain (adib. osotasun-egiaztapena huts egin duen fitxategi bat), bakoitza kode, osagai eta locale bat soilik, eta inoiz ez kate-edukirik edo testu itzulirik.','Unsafe locale: %s'=>'Locale ez-segurua: %s','Manifest unavailable: %s'=>'Manifestua ez dago erabilgarri: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Ezin izan dira osagai aktiboak zehaztu; lehendik zegoen indize bateratua aldatu gabe utzi da.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Ezin izan dira instalatutako plugin/itxurak zehaztu; arakatze-garbiketa saltatu da, ez da ezer ezabatu.','Sweep aborted without orphaning anything: %s.'=>'Arakatze-garbiketa bertan behera utzi da ezer umezurtz utzi gabe: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Garbiketa exekutatu da, baina bere aldaketa batzuk ezin izan dira itzulpen-indizean erregistratu; hurrengo garbiketak berriro saiatuko ditu.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' locale-aren indize bateratua berreraiki da, baina itzulpen-indizeak ezin izan du erregistratu; hurrengo berreraikuntzak berriro saiatuko da.','Could not write the staged merged index.'=>'Ezin izan da prestatutako indize bateratua idatzi.','Re-parsed entry count did not match the built index.'=>'Berriro analizatutako sarrera-kopuruak ez du eraikitako indizearekin bat egiten.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Ezin izan da \'%s\' locale-aren indize bateratua bere lekuan jarri; zerbitzatzen zen aurreko indizea (bazegoen) kendu egin da erdi eguneratuta uzteko ordez. Ez da default domain-eko osagarririk zerbitzatuko locale honetarako hurrengo berreraikuntza arrakastatsua egin arte.','Could not open zip: %s'=>'Ezin izan da zip-a ireki: %s','Zip has no manifest.json.'=>'Zip-ak ez du manifest.json-ik.','manifest.json in the zip is not valid JSON.'=>'Zip-eko manifest.json ez da baliozko JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json-eko \'%s\' ez dator bat espero den balioarekin.','Another installation is running; try again in a moment.'=>'Beste instalazio bat exekutatzen ari da; saiatu berriro une batean.','Not a valid server_build_id: %s'=>'Ez da baliozko server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Paketearen manifestuko \'%1$s\' mota ez dator bat eskatutako \'%2$s\' motarekin.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Paketearen text domain-a (\'%1$s\') ez dator bat gune honetako osagaiaren kopiarekin (\'%2$s\'), beraz ez da instalatu.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Emandako \'%1$s\' domeinua ez dator bat paketearen manifestuko \'%2$s\' slug-arekin ezta \'%3$s\' text_domain-arekin ere.','Unsafe slug: %s'=>'Slug ez-segurua: %s','Unsafe text_domain: %s'=>'text_domain ez-segurua: %s','The package has no %s for its own text domain.'=>'Paketeak ez du %s bere testu-domeinurako.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json falta da edo \'%s\' baliogabea du.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json falta da edo \'entries\' baliogabea du.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json falta da edo \'files\' baliogabea du.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json falta da edo \'extra_domains\' baliogabea du.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json falta da edo \'build_no\' baliogabea du.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json fitxategiko \'server_build_id\' ez da build id baliozko bat.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json fitxategiko \'contract\' ez da bertsio-kate baliozko bat.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json fitxategiko \'kind\' \'plugin\' edo Itxura (\'theme\') izan behar da.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json fitxategiak \'default_domain_entries\' baliogabea du.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json fitxategiak \'default_domain_files\' baliogabea du.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest falta da edo \'%s\' baliogabea du.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest elementuko \'server_build_id\' ez da build id baliozko bat.','No record for %s'=>'Ez dago erregistrorik hauentzat: %s','One or more served files no longer match the manifest.'=>'Zerbitzatutako fitxategi bat edo gehiago ez datoz bat manifestuarekin.','No previous build to roll back to.'=>'Ez dago aurreko build-ik atzera egiteko.','The change could not be recorded in the translation index; please try again.'=>'Ezin izan da aldaketa itzulpen-indizean erregistratu; saiatu berriro.','Unknown kind: %s'=>'Kind ezezaguna: %s','Unsafe domain: %s'=>'Domeinu ez-segurua: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'\'%1$s\' testu-domeinua (%2$s) instalatutako beste osagai baterako zerbitzatzen ari da jada (%3$s); ez da ezer instalatu.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Atzera egiteak \'%1$s\' (%2$s) gainidatziko luke, eta hori instalatutako beste osagai baterako zerbitzatzen ari da (%3$s); ez da ezer aldatu.','Zip is missing expected file: %s'=>'Zipean falta da espero zen fitxategia: %s','sha256 mismatch for %s'=>'sha256 ez dator bat honekin: %s','The package declares no main translation file.'=>'Paketeak ez du itzulpen-fitxategi nagusirik zehazten.','Zip is missing expected default file: %s'=>'Zipean falta da espero zen fitxategi lehenetsia: %s','sha256 mismatch for default/%s'=>'sha256 ez dator bat honekin: default/%s','Could not stage %s'=>'Ezin izan da prestatu: %s','Could not stage default/%s'=>'Ezin izan da prestatu: default/%s','Entry count mismatch for %s'=>'Sarrera kopuruak ez datoz bat honetarako: %s','Could not verify entry count for %s'=>'Ezin izan da sarrera kopurua egiaztatu honetarako: %s','l10n.php entry count mismatch for %s'=>'l10n.php sarrera kopuruak ez datoz bat honetarako: %s','Default supplement entry count mismatch.'=>'Osagarri lehenetsiaren sarrera kopuruak ez datoz bat.','The package produced no servable main translation file.'=>'Paketeak ez du zerbitzatu daitekeen itzulpen-fitxategi nagusirik sortu.','Could not prepare %s for rollback.'=>'Ezin izan da %s atzera egiteko prestatu.','Could not back up %s before replacing it.'=>'Ezin izan da %s babeskopia egin ordeztu aurretik.','Could not move %s into place.'=>'Ezin izan da %s bere lekuan jarri.','English (United States)'=>'Ingelesa (Estatu Batuak)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ez dago erabilgarri: %s','could not read _manifest.json: %s'=>'ezin izan da _manifest.json irakurri: %s','failed to parse _manifest.json: %s'=>'Ezin izan da _manifest.json analizatu: %s','_manifest.json has an unexpected structure'=>'_manifest.json fitxategiak ustekabeko egitura du','Could not create the package archive.'=>'Ezin izan da paketearen artxiboa sortu.','No writable temporary directory is available for packaging.'=>'Ez dago idatz daitekeen aldi baterako direktoriorik paketatzeko.','A file in the component could not be read, so it was not packaged.'=>'Osagaiko fitxategi bat ezin izan da irakurri, beraz ez da paketatu.','Only plugins and themes can be packaged.'=>'Pluginak eta gaiak soilik paketa daitezke.','The component\'s main file was not found.'=>'Osagaiaren fitxategi nagusia ez da aurkitu.','The component is not inside the plugins or themes directory.'=>'Osagaia ez dago pluginen edo gaien direktorioaren barruan.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim-ek denbora agortu du urrats honetarako eta hurrengo egiaztapenean jarraituko du.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim-ek ezin izan du gune hau egiaztatu, beraz ez da ezer deskargatuko edo instalatuko egiaztapena behar bezala egin arte.','Registration response was missing required fields.'=>'Izen-emateko erantzunean beharrezko eremuak falta ziren.','No pending challenge to verify.'=>'Ez dago egiaztatzeko zain dagoen erronkarik.','Verify response was missing site_token.'=>'Egiaztapen-erantzunean site_token falta zen.','No site id is on file to rotate a token for.'=>'Ez dago tokena berritzeko gune-identifikatzailerik gordeta.','Rotate-token response was missing site_token.'=>'Token-errotazioaren erantzunean site_token falta zen.','nonce must be a hexadecimal string.'=>'nonce-a kate hamaseitarra izan behar da.','No pending challenge for this nonce.'=>'Ez dago nonce honetarako zain dagoen erronkarik.','Too many requests.'=>'Eskaera gehiegi.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Gune honek %1$d osagai ditu %2$d hizkuntzatan zehar, eta horrek %3$d egiaztapen-lote behar ditu; Babilim-ek gehienez %4$d kudea ditzake exekuzio bakoitzean. Murriztu kudeatutako hizkuntzak Ezarpenak atalean edo desaktibatu erabiltzen ez diren pluginak eta gaiak, eta sakatu Egiaztatu berriro orain.','Babilim could not finish checking this site.'=>'Babilim-ek ezin izan du gune hau egiaztatzen amaitu.','This site\'s address is too long for Babilim to register.'=>'Gune honen helbidea luzeegia da Babilim-ek erregistratzeko.','This site\'s locale code is not one Babilim can register.'=>'Gune honen hizkuntza-kodea ez da Babilim-ek erregistra dezakeen bat.','The download response was missing a usable location.'=>'Deskargaren erantzunean ez zegoen erabilgarri zen kokalekurik.','The service\'s upload offer was incomplete.'=>'Zerbitzuaren igoera-eskaintza osatugabea zen.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Osagai hau zerbitzuak onartzen duena baino handiagoa da, beraz ezin da igo.','The packaged component could not be read.'=>'Paketatutako osagaia ezin izan da irakurri.','A part of the upload kept failing, so the upload was cancelled.'=>'Igoeraren zati batek huts egiten jarraitu zuen, beraz igoera bertan behera utzi da.','Could not read: %s'=>'Ezin izan da irakurri: %s']];